   432	exr_decoding_choose_default_routines (
   433	    exr_const_context_t ctxt, int part_index, exr_decode_pipeline_t* decode)
   434	{
   435	    int32_t isdeep = 0, chanstofill = 0, chanstounpack = 0, sametype = -2,
   436	            sameouttype = -2, samebpc = 0, sameoutbpc = 0, hassampling = 0,
   437	            hastypechange = 0, simpinterleave = 0, simpinterleaverev = 0,
   438	            simplineoff = 0, sameoutinc = 0;
   439	    uint8_t* interleaveptr = NULL;
   440	    EXR_PROMOTE_READ_CONST_CONTEXT_AND_PART_OR_ERROR (ctxt, part_index);
   441	    if (!decode) return pctxt->standard_error (pctxt, EXR_ERR_INVALID_ARGUMENT);
   442	
   443	    if (decode->context != ctxt || decode->part_index != part_index)
   444	        return pctxt->print_error (
   445	            pctxt,
   446	            EXR_ERR_INVALID_ARGUMENT,
   447	            "Cross-wired request for default routines from different context / part");
   448	
   449	    isdeep = (part->storage_mode == EXR_STORAGE_DEEP_SCANLINE ||
   450	              part->storage_mode == EXR_STORAGE_DEEP_TILED)
   451	                 ? 1
   452	                 : 0;
   453	
   454	    for (int c = 0; c < decode->channel_count; ++c)
   455	    {
   456	        exr_coding_channel_info_t* decc = (decode->channels + c);
   457	
   458	        if (decc->height == 0 || !decc->decode_to_ptr) continue;
   459	
   460	        /*
   461	         * if a user specifies a bad pixel stride / line stride
   462	         * we can't know this realistically, and they may want to
   463	         * use 0 to cause things to collapse for testing purposes
   464	         * so only test the values we know we use for decisions
   465	         */
   466	        if (decc->user_bytes_per_element != 2 &&
   467	            decc->user_bytes_per_element != 4)
   468	            return pctxt->print_error (
   469	                pctxt,
   470	                EXR_ERR_INVALID_ARGUMENT,
   471	                "Invalid / unsupported output bytes per element (%d) for channel %c (%s)",
   472	                (int) decc->user_bytes_per_element,
   473	                c,
   474	                decc->channel_name);
   475	
   476	        if (decc->user_data_type != (uint16_t) (EXR_PIXEL_HALF) &&
   477	            decc->user_data_type != (uint16_t) (EXR_PIXEL_FLOAT) &&
   478	            decc->user_data_type != (uint16_t) (EXR_PIXEL_UINT))
   479	            return pctxt->print_error (
   480	                pctxt,
   481	                EXR_ERR_INVALID_ARGUMENT,
   482	                "Invalid / unsupported output data type (%d) for channel %c (%s)",
   483	                (int) decc->user_data_type,
   484	                c,
   485	                decc->channel_name);
   486	
   487	        if (sametype == -2)
   488	            sametype = (int32_t) decc->data_type;
   489	        else if (sametype != (int32_t) decc->data_type)
   490	            sametype = -1;
   491	
   492	        if (sameouttype == -2)
   493	            sameouttype = (int32_t) decc->user_data_type;
   494	        else if (sameouttype != (int32_t) decc->user_data_type)
   495	            sameouttype = -1;
   496	
   497	        if (samebpc == 0)
   498	            samebpc = decc->bytes_per_element;
   499	        else if (samebpc != decc->bytes_per_element)
   500	            samebpc = -1;
   501	
   502	        if (sameoutbpc == 0)
   503	            sameoutbpc = decc->user_bytes_per_element;
   504	        else if (sameoutbpc != decc->user_bytes_per_element)
   505	            sameoutbpc = -1;
   506	
   507	        if (decc->x_samples != 1 || decc->y_samples != 1) hassampling = 1;
   508	
   509	        ++chanstofill;
   510	        if (decc->user_pixel_stride != decc->bytes_per_element) ++chanstounpack;
   511	        if (decc->user_data_type != decc->data_type) ++hastypechange;
   512	
   513	        if (simplineoff == 0)
   514	            simplineoff = decc->user_line_stride;
   515	        else if (simplineoff != decc->user_line_stride)
   516	            simplineoff = -1;
   517	
   518	        if (simpinterleave == 0)
   519	        {
   520	            interleaveptr     = decc->decode_to_ptr;
   521	            simpinterleave    = decc->user_pixel_stride;
   522	            simpinterleaverev = decc->user_pixel_stride;
   523	        }
   524	        else
   525	        {
   526	            if (simpinterleave > 0 &&
   527	                decc->decode_to_ptr !=
   528	                    (interleaveptr + c * decc->user_bytes_per_element))
   529	            {
   530	                simpinterleave = -1;
   531	            }
   532	            if (simpinterleaverev > 0 &&
   533	                decc->decode_to_ptr !=
   534	                    (interleaveptr - c * decc->user_bytes_per_element))
   535	            {
   536	                simpinterleaverev = -1;
   537	            }
   538	            if (simpinterleave < 0 && simpinterleaverev < 0)
   539	                interleaveptr = NULL;
   540	        }
   541	
   542	        if (sameoutinc == 0)
   543	            sameoutinc = decc->user_pixel_stride;
   544	        else if (sameoutinc != decc->user_pixel_stride)
   545	            sameoutinc = -1;
   546	    }
   547	
   548	    if (simpinterleave != sameoutbpc * decode->channel_count)
   549	        simpinterleave = -1;
   550	    if (simpinterleaverev != sameoutbpc * decode->channel_count)
   551	        simpinterleaverev = -1;
